import { Component, createMemo, createSignal, Show } from "solid-js";

import {
	Background3d,
	BackgroundLayer3d,
	Camera3d,
	Model3d,
	ModelGroup3d,
	Scene3d,
} from "#core/ui-next/components/scene-3d.jsx";
import { useCivSelectModelContext } from "#core/ui-next/screens/create-game/civ-select-model.js";
import { useLeaderSelectModelContext } from "#core/ui-next/screens/create-game/leader-select-model.js";
import { LayoutModel, useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

const TRIGGER_HASH_SEQUENCE_TRIGGER = WorldUI.hash("SEQUENCE");

export interface GrayscaleLeaderBanner3dProps {
	bgOnly?: boolean;
}

export const LeaderBanner3d: Component<GrayscaleLeaderBanner3dProps> = (props) => {
	const leaderModel = useLeaderSelectModelContext();
	const civModel = useCivSelectModelContext();
	const layout = LayoutModel.get();

	const bannerAsset = createMemo(() =>
		civModel.selectedCiv().civID == "RANDOM"
			? "CIVILIZATION_RANDOM_BANNER_GAME_ASSET"
			: `${civModel.selectedCiv().civID}_BANNER_GAME_ASSET`,
	);
	const headerHeight = layout.toScaledPixels(144);
	const footerHeight = layout.toScaledPixels(76);

	const primaryColor = createMemo(() => leaderModel.selectedLeader().colors?.primaryColor);
	const secondaryColor = createMemo(() => leaderModel.selectedLeader().colors?.secondaryColor);

	return (
		<Scene3d name="leader-banner-scene">
			<Background3d>
				<BackgroundLayer3d
					name="bg-texture"
					texture="grey-box-texture"
				/>
				<BackgroundLayer3d
					name="header"
					size={{ x: layout.screenWidthScaled(), y: headerHeight() }}
					offset={{ x: 0, y: 0 }}
					alignX={AlignMode.Minimum}
					alignY={AlignMode.Minimum}
					texture="grey-box-texture-dark"
				/>
				<BackgroundLayer3d
					name="footer"
					size={{ x: layout.screenWidthScaled(), y: footerHeight() }}
					offset={{ x: 0, y: 0 }}
					alignX={AlignMode.Minimum}
					alignY={AlignMode.Maximum}
					texture="grey-box-texture-dark"
				/>
			</Background3d>
			<Show when={!props.bgOnly}>
				<Camera3d
					cameraPos={{ x: 0, y: -40, z: 11 }}
					subjectPos={{ x: -17, y: 5, z: 10.5 }}
				/>
				<ModelGroup3d name="CivDetails3dModelGroup">
					<Model3d
						model="LEADER_LIGHTING_SCENE_CHAR_SELECT_GAME_ASSET"
						angle={0}
					/>
					<Model3d
						model={leaderModel.selectedLeader().model}
						state="IDLE_CharSelect"
						location={{ offset: { x: -5, y: 0, z: 0 } }}
					/>
					<Model3d
						model={bannerAsset()}
						tintColor1={primaryColor()}
						tintColor2={secondaryColor()}
						location={{ offset: { x: 0, y: 20, z: 17 } }}
						scale={1.4}
					/>
				</ModelGroup3d>
			</Show>
		</Scene3d>
	);
};

export const LeaderPedestalBanner3d: Component<GrayscaleLeaderBanner3dProps> = (props) => {
	const leaderModel = useLeaderSelectModelContext();
	const civModel = useCivSelectModelContext();
	const [animState, setAnimState] = createSignal("SPAWN_Trim16");

	const bannerAsset = createMemo(() =>
		civModel.selectedCiv().civID == "RANDOM"
			? "CIVILIZATION_RANDOM_BANNER_GAME_ASSET"
			: `${civModel.selectedCiv().civID}_BANNER_GAME_ASSET`,
	);

	const primaryColor = createMemo(() => leaderModel.selectedLeader().colors?.primaryColor);
	const secondaryColor = createMemo(() => leaderModel.selectedLeader().colors?.secondaryColor);

	const isSmallScreen = useIsSmallScreen();

	return (
		<Scene3d name="leader-banner-scene">
			<Show when={!props.bgOnly}>
				<Camera3d
					cameraPos={{ x: 0, y: -40, z: 11 }}
					subjectPos={{ x: -17, y: 5, z: 10.5 }}
				/>
				<ModelGroup3d name="CivDetails3dModelGroup">
					<Model3d
						model="LEADER_LIGHTING_SCENE_CHAR_SELECT_GAME_ASSET"
						angle={0}
					/>
					<Model3d
						model="LEADER_SELECTION_PEDESTAL"
						angle={120}
						scale={0.9}
						location={{ offset: isSmallScreen() ? { x: 0, y: -6, z: 0 } : { x: -3, y: -6, z: 0 } }}
					/>
					<Model3d
						model={leaderModel.selectedLeader().model}
						state="IDLE_CharSelect"
						location={{ offset: isSmallScreen() ? { x: 0, y: -6, z: 0 } : { x: -2, y: -6, z: 0 } }}
					/>
					<Model3d
						model={bannerAsset()}
						state={animState()}
						tintColor1={primaryColor()}
						tintColor2={secondaryColor()}
						location={{ offset: { x: 0, y: 20, z: 17 } }}
						scale={1.6}
						angle={-25}
						onTrigger={(hash) => {
							if (hash == TRIGGER_HASH_SEQUENCE_TRIGGER) {
								setAnimState("IDLE");
							}
						}}
					/>
				</ModelGroup3d>
			</Show>
		</Scene3d>
	);
};

export const LeaderZoomed3d: Component = () => {
	const leaderModel = useLeaderSelectModelContext();
	const layout = LayoutModel.get();

	const headerHeight = layout.toScaledPixels(144);
	const footerHeight = layout.toScaledPixels(76);

	return (
		<Scene3d name="leader-banner-zoomed-scene">
			<Background3d>
				<BackgroundLayer3d
					name="bg-texture"
					texture="grey-box-texture"
				/>
				<BackgroundLayer3d
					name="header"
					size={{ x: layout.screenWidthScaled(), y: headerHeight() }}
					offset={{ x: 0, y: 0 }}
					alignX={AlignMode.Minimum}
					alignY={AlignMode.Minimum}
					texture="grey-box-texture-dark"
				/>
				<BackgroundLayer3d
					name="footer"
					size={{ x: layout.screenWidthScaled(), y: footerHeight() }}
					offset={{ x: 0, y: 0 }}
					alignX={AlignMode.Minimum}
					alignY={AlignMode.Maximum}
					texture="grey-box-texture-dark"
				/>
			</Background3d>
			<Camera3d
				cameraPos={{ x: 0, y: -20, z: 17 }}
				subjectPos={{ x: 0, y: 10, z: 10 }}
			/>
			<ModelGroup3d name="CivDetails3dModelGroup">
				<Model3d
					model="LEADER_LIGHTING_SCENE_CHAR_SELECT_GAME_ASSET"
					angle={0}
				/>
				<Model3d
					model={leaderModel.selectedLeader().model}
					state={"IDLE_CharSelect"}
				/>
			</ModelGroup3d>
		</Scene3d>
	);
};
